import numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.model_selection import train_test_splitfrom sklearn.preprocessing import StandardScalerfrom sklearn.preprocessing import LabelEncoderfrom sklearn.linear_model import LogisticRegressionfrom matplotlib.colors import ListedColormapfrom sklearn.metrics import accuracy_scoreclownfish_data = pd.read_excel('/Users/ggraham/Desktop/multiome_poa/Reference/Complete Data Frame (Hormones, Behavior, Size, Gonads) GG.xlsx')clownfish_data_known_sex = clownfish_data[(clownfish_data['Status'].isin(['M','F','D']))]clown_x = clownfish_data_known_sex[['mass_final_cm','Log_11KT']]clown_x['Log_11KT'][9] = clownfish_data_known_sex['Log_11KT'][clownfish_data_known_sex['Status']=='M'].mean()clown_x['Log_11KT'][8] = clownfish_data_known_sex['Log_11KT'][clownfish_data_known_sex['Status']=='F'].mean()clown_y = clownfish_data_known_sex[['Status']]    # Apply LabelEncoder first to convert string labels to numeric valuesle = LabelEncoder()y_encoded = le.fit_transform(clown_y.values.ravel())# Now perform the train-test split with the encoded labelsX_train, X_test, y_train, y_test = train_test_split(clown_x,                                                    y_encoded,                                                    test_size = 0.3,                                                     random_state =1,                                                     stratify = y_encoded)# Apply StandardScalersc = StandardScaler()sc.fit(X_train)x_train_std = sc.transform(X_train)x_test_std = sc.transform(X_test)# apply logistic regressionlr = LogisticRegression(C = 100, solver = 'lbfgs')#c is inversely proportional to the regularization paramter, smaller number means#more regularizationlr.fit(x_train_std, y_train)def plot_decision_regions(X, y, classifier, test_idx=None,                          resolution=0.02):    # Setup marker generator and color map    markers = ('o', 's', '^', 'v', '<')    colors = ('red', 'blue', 'lightgreen', 'gray', 'cyan')    cmap = ListedColormap(colors[:len(np.unique(y))])        # Plot the decision surface    x1_min, x1_max = X[:, 0].min() - 1, X[:, 0].max() + 1    x2_min, x2_max = X[:, 1].min() - 1, X[:, 1].max() + 1    xx1, xx2 = np.meshgrid(np.arange(x1_min, x1_max, resolution),                           np.arange(x2_min, x2_max, resolution))        # Make predictions on the grid points and convert to integers    Z = classifier.predict(np.array([xx1.ravel(), xx2.ravel()]).T)    Z = Z.astype(int)  # Ensure numeric values for contourf    Z = Z.reshape(xx1.shape)        plt.contourf(xx1, xx2, Z, alpha=0.3, cmap=cmap)    plt.xlim(xx1.min(), xx1.max())    plt.ylim(xx2.min(), xx2.max())        # Plot class examples    for idx, cl in enumerate(np.unique(y)):        plt.scatter(x=X[y == cl, 0],                    y=X[y == cl, 1],                    alpha=0.8,                    c=colors[idx],                    marker=markers[idx],                    label=f'Class {cl} ({le.inverse_transform([cl])[0]})',  # Show original label                    edgecolor='black')        # Highlight test examples    if test_idx:        X_test, y_test = X[test_idx, :], y[test_idx]        plt.scatter(X_test[:, 0], X_test[:, 1],                    c='none', edgecolor='black', alpha=1.0,                    linewidth=1, marker='o',                    s=100, label='Test set')# Combine train and test data for visualizationX_combined_std = np.vstack((x_train_std, x_test_std))y_combined = np.hstack((y_train, y_test))# Plot decision regionsplot_decision_regions(X=X_combined_std,                       y=y_combined,                       classifier=lr,                      test_idx=range(len(y_train), len(y_combined)))plt.xlabel('Standardized Mass')plt.ylabel('Standardized 11KT')plt.legend(loc='upper right')plt.tight_layout()plt.show()#predictions#here, each row is an individual, and each column is the likelihood it belongs to a specific#sexlr.predict_proba(x_test_std)lr.predict_proba(x_test_std).argmax(axis=1)# so this would be I think F F D M M M #I should rerun this but with dominants as test casespreds = lr.predict_proba(x_test_std)